/* From Uiverse.io by Nawsome - Tags: loader, placeholder */
.__UIV_SCOPE__ .loader {
  position: relative;
  width: 240px;
  height: 130px;
  margin-bottom: 10px;
  border: 1px solid #d3d3d3;
  padding: 15px;
  background-color: #e3e3e3;
  overflow: hidden;
}

.__UIV_SCOPE__ .loader:after {
  content: "";
  position: absolute;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  background: linear-gradient(110deg, rgba(227, 227, 227, 0) 0%, rgba(227, 227, 227, 0) 40%, rgba(227, 227, 227, 0.5) 50%, rgba(227, 227, 227, 0) 60%, rgba(227, 227, 227, 0) 100%);
  animation: gradient-animation_2 1.2s linear infinite;
}

.__UIV_SCOPE__ .loader .wrapper {
  width: 100%;
  height: 100%;
  position: relative;
}

.__UIV_SCOPE__ .loader .wrapper > div {
  background-color: #cacaca;
}

.__UIV_SCOPE__ .loader .circle {
  width: 50px;
  height: 50px;
  border-radius: 50%;
}

.__UIV_SCOPE__ .loader .button {
  display: inline-block;
  height: 32px;
  width: 75px;
}

.__UIV_SCOPE__ .loader .line-1 {
  position: absolute;
  top: 11px;
  left: 58px;
  height: 10px;
  width: 100px;
}

.__UIV_SCOPE__ .loader .line-2 {
  position: absolute;
  top: 34px;
  left: 58px;
  height: 10px;
  width: 150px;
}

.__UIV_SCOPE__ .loader .line-3 {
  position: absolute;
  top: 57px;
  left: 0px;
  height: 10px;
  width: 100%;
}

.__UIV_SCOPE__ .loader .line-4 {
  position: absolute;
  top: 80px;
  left: 0px;
  height: 10px;
  width: 92%;
}

@keyframes gradient-animation_2 {
  0% {
    transform: translateX(-100%);
  }

  100% {
    transform: translateX(100%);
  }
}
